import React, {useState} from "react";
import Button from "@mui/material/Button";
import Menu from "@mui/material/Menu";
import MenuItem from "@mui/material/MenuItem";

function OurMenu() {
  return (

      function DropdownMui() {
        const [anchorEl, setAnchorEl] = useState(null);

        const handleClick = (event) => {
          setAnchorEl(event.currentTarget);
        };
        const handleClose = () => {
          setAnchorEl(null);
        };

        return (
          <div>
            <Button
              aria-controls="simple-menu"
              aria-haspopup="true"
              onClick={handleClick}
              variant="contained"
              color="primary"
            >
              Menu
            </Button>
            <Menu
              id="simple-menu"
              anchorEl={anchorEl}
              open={Boolean(anchorEl)}
              onClose={handleClose}
            >
              <MenuItem onClick={handleClose}><a href="/team">Muffins</a></MenuItem>
              <MenuItem onClick={handleClose}><a href="/menu">Cupkes</a></MenuItem>
              <MenuItem onClick={handleClose}><a href="/contact">Vegan</a></MenuItem>
            </Menu>
          </div>
        );
      }
  );
}

export default OurMenu;
